for row in rows:
    n=int(row['id'].split('.')[1]);row['statement']=precise[n]
    row['status']=('open — completion closure unresolved' if n==39 else
                   'open — general two-scheme formulation; contextual examples proved' if n==40 else
                   'false as written; corrected statement proved' if n in false else
                   'known; exact source matched and reduction proved' if n in {19,20,32,33,45} else
                   'proved in the explicitly stated reconstruction')
    row['proof_or_reference']=f'PROOFS.tex section H035.{n}; research/SECOND_CHECKS.md H035.{n}'
    row['later']=later.get(n,'Complete proof in this run; standard inputs are identified in PROOFS.tex and references.bib.')
    row['check_events']=f'CHECK_EVENTS.tsv: H035.{n}; second pass in research/SECOND_CHECKS.md'
    row['confidence']=('High for proved reductions; no confidence claim of full closure' if n==39 else
                       'High for contextual examples and nonproper counterexample; broader scope unspecified' if n==40 else
                       'High for stated mathematical reconstruction; disputed ink separately graded in READINGS.tsv')
    if 22<=n<=26:
        row['date']='Inserted typescript undated; authorship unestablished; folder catalogue dating is not a date for this leaf'
    if n==16:row['reconstruction']='Canonical-module equivalence is ours; the ink says differentials, and the Kähler interpretation is refuted.'
    if n==37:row['reconstruction']='R/F mismatch retained; the first graded coefficient remains uncertain. Our proof explicitly handles gr_J(R) and gr_J(A).'
with p.open('w') as stream:
    writer=csv.DictWriter(stream,fields,delimiter='\t');writer.writeheader();writer.writerows(rows)
print('Refined',len(rows),'statements with hypotheses; open rows:',[r['id'] for r in rows if r['status'].startswith('open')])
